};

// Invert 4x4 matrix (Gauss-Jordan), return determinant
static double invert4(const Matrix4d& A, Matrix4d& Ainv, int& ising) {
    Matrix4d Mx = A;
    Ainv = Matrix4d::Identity();
    ising = 0;
    double det = 1.0;
    for (int i = 0; i < 4; i++) {
        int piv = i;
        double maxv = std::abs(Mx(i,i));
        for (int r = i+1; r < 4; r++)
            if (std::abs(Mx(r,i)) > maxv) { maxv = std::abs(Mx(r,i)); piv = r; }
        if (maxv < 1e-300) { ising = 2; return 0.0; }
        if (piv != i) { Mx.row(i).swap(Mx.row(piv)); Ainv.row(i).swap(Ainv.row(piv)); det = -det; }
        double d = Mx(i,i);
        det *= d;
        for (int c = 0; c < 4; c++) { Mx(i,c) /= d; Ainv(i,c) /= d; }
        for (int r = 0; r < 4; r++) {
            if (r == i) continue;
            double f = Mx(r,i);
            if (f != 0.0)
                for (int c = 0; c < 4; c++) { Mx(r,c) -= f*Mx(i,c); Ainv(r,c) -= f*Ainv(i,c); }
        }
    }
    return det;
}

