        G(0,0)=g1; G(1,1)=g1; G(2,2)=g1;
        G(0,1)=g2; G(0,2)=g2; G(1,0)=g2; G(1,2)=g2; G(2,0)=g2; G(2,1)=g2;
        G(3,3)=GG; G(4,4)=GG; G(5,5)=GG;

        std::vector<Matrix<double,6,3>> C(4);
        for (int i = 0; i < 4; i++) {
            C[i] = Matrix<double,6,3>::Zero();
            double dx = Hinv(i,1), dy = Hinv(i,2), dz = Hinv(i,3);
