        }

        int IOPT = it + 11;
        double hd = hdeter / 36.0;
        if (IOPT <= 16) hd *= 2.0;

        Matrix<double,12,12> Ktet = Matrix<double,12,12>::Zero();
        for (int a = 0; a < 4; a++)
            for (int b = 0; b < 4; b++)
                Ktet.block<3,3>(3*a,3*b) = C[a].transpose() * G * C[b] * hd;

        for (int a = 0; a < 4; a++) {
            int ga = M[it][a] - 1;
            for (int b = 0; b < 4; b++) {
                int gb = M[it][b] - 1;
                K.block<3,3>(3*ga,3*gb) += Ktet.block<3,3>(3*a,3*b);
            }
        }
    }

    std::cout << "{\"stiffness_matrix\":[";
